        enable: true,
        model: "gpt-4o-mini",
        timeoutMs: 12_000,
        /** 请求彼此独立；完成一批立刻再取下一批，不是等固定节拍。 */
        maxConcurrent: 3,
        /** 单次请求最多打包的标题数；队首不足这个数也立刻发，不等凑批。 */
        batchSize: 6,
        /** 只保留有限的待判任务；快速滚动时淘汰最远、已断开和身后的标题 */
        maxPendingJobs: 30,
        /** 前瞻预取：标题进入视窗前这么多屏就先发出去，滚到时大概率已缓存 */
